import React from "react";
import logo from "../assests/vighnexlogo.png";

export default function Footer({ scrollTo }) {
  const container = {
    width: "min(1180px,92%)",
    margin: "0 auto",
  };

  return (
    <footer
        style={{
          background: "#061b2b",
          color: "#b7c7d0",
          padding: "55px 0 22px",
        }}
      >
        <div style={container}>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1.5fr 1fr 1fr 1fr",
              gap: 40,
              paddingBottom: 40,
            }}
          >
            <div>
              <img
                src={logo}
                alt="Vighnex Technologies"
                style={{
                  width: 205,
                  height: 65,
                  objectFit: "contain",
                  objectPosition: "left center",
                  display: "block",
                  filter: "brightness(0) invert(1)",
                }}
              />

              <p
                style={{
                  fontSize: 13,
                  lineHeight: 1.8,
                  maxWidth: 320,
                  marginTop: 14,
                  color: "#aebec8",
                }}
              >
                Building meaningful digital experiences where traditional
                values meet modern technology. Create. Build. Deploy. Grow.
              </p>
            </div>

            {[
              [
                "Company",
                [
                  ["About Us", "about"],
                  ["Why Choose Us", "why"],
                  ["Our Work", "projects"],
                  ["Contact", "contact"],
                ],
              ],
              [
                "Services",
                [
                  ["Web Development", "services"],
                  ["UI/UX Design", "services"],
                  ["Digital Marketing", "services"],
                  ["Mobile Development", "services"],
                  ["Cloud Development", "services"],
                ],
              ],
              [
                "Let's Connect",
                [
                  ["Start a Project", "contact"],
                  ["FAQs", "faq"],
                  ["Technology", "technology"],
                  ["Our Process", "process"],
                ],
              ],
            ].map(([heading, links]) => (
              <div key={heading}>
                <h4
                  style={{
                    color: "#fff",
                    marginBottom: 17,
                    fontSize: 14,
                  }}
                >
                  {heading}
                </h4>

                <div style={{ display: "grid", gap: 10 }}>
                  {links.map(([text, id]) => (
                    <button
                      key={text}
                      onClick={() => scrollTo(id)}
                      style={{
                        background: "transparent",
                        border: 0,
                        color: "#aebec8",
                        textAlign: "left",
                        cursor: "pointer",
                        fontSize: 12,
                        padding: 0,
                      }}
                    >
                      {text}
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>

          <div
            style={{
              borderTop: "1px solid rgba(255,255,255,.1)",
              paddingTop: 22,
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: 20,
              flexWrap: "wrap",
              fontSize: 11,
            }}
          >
            <span>© 2026 Vighnex Technologies. All Rights Reserved.</span>

            <div style={{ display: "flex", gap: 8 }}>
              {[
                ["in", "https://www.linkedin.com"],
                ["◎", "https://www.instagram.com"],
                ["f", "https://www.facebook.com"],
                ["▶", "https://www.youtube.com"],
              ].map(([text, href]) => (
                <a
                  key={href}
                  href={href}
                  target="_blank"
                  rel="noreferrer"
                  style={{
                    width: 34,
                    height: 34,
                    border: "1px solid #385263",
                    borderRadius: "50%",
                    display: "grid",
                    placeItems: "center",
                    color: "#c4d2d9",
                    textDecoration: "none",
                  }}
                >
                  {text}
                </a>
              ))}
            </div>
          </div>
        </div>
      </footer>
  );
}
